#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <arpa/inet.h>
#include <netinet/in.h>

#define ROLE_ADMIN  0x01
#define ROLE_USER   0x02
#define ROLE_GUEST  0x04

#define MAX_QUERY_LEN 253
#define CACHE_DIR "/var/cache/dnsresolve"

typedef struct {
    unsigned int role;
    unsigned int uid;
    char username[64];
} session_t;

typedef struct {
    char qname[MAX_QUERY_LEN + 1];
    uint16_t qtype;
    uint32_t ttl;
    char rdata[256];
} dns_record_t;

static int validate_session(const session_t *sess) {
    if (!sess) return -1;
    if (sess->role == 0) return -1;
    if (sess->username[0] == '\0') return -1;
    return 0;
}

static int check_query_permission(const session_t *sess, const char *domain) {
    if (validate_session(sess) != 0) return -1;

    /* Guests can only query .public domains */
    if (sess->role & ROLE_GUEST) {
        size_t dlen = strlen(domain);
        if (dlen < 7 || strcmp(domain + dlen - 7, ".public") != 0) {
            return -1;
        }
    }
    return 0;
}

static int sanitize_domain(const char *input, char *output, size_t outlen) {
    size_t i, len = strlen(input);
    if (len == 0 || len > MAX_QUERY_LEN) return -1;

    for (i = 0; i < len && i < outlen - 1; i++) {
        char c = input[i];
        if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
            (c >= '0' && c <= '9') || c == '.' || c == '-') {
            output[i] = c;
        } else {
            return -1;
        }
    }
    output[i] = '\0';
    return 0;
}

/* Generate a cache file path for storing DNS results */
static int get_cache_path(char *path, size_t pathlen, const char *domain,
                          const session_t *sess) {
    char sanitized[MAX_QUERY_LEN + 1];
    if (sanitize_domain(domain, sanitized, sizeof(sanitized)) != 0)
        return -1;

    snprintf(path, pathlen, "%s/%s_%u.cache", CACHE_DIR, sanitized, sess->uid);
    return 0;
}

/* Create a temporary file for atomic cache writes.
 * Uses mkstemp for secure temporary file creation with
 * unpredictable names to prevent symlink/race attacks. */
static int create_cache_staging(const char *cache_path, const session_t *sess) {
    char staging_path[512];
    int fd;
    (void)cache_path; /* staging location is independent of cache path */
    (void)sess;

    snprintf(staging_path, sizeof(staging_path),
             "%s/.staging_XXXXXX", CACHE_DIR);

    /* mkstemp: atomically creates a unique file with O_EXCL semantics,
     * preventing symlink attacks and race conditions */
    fd = mkstemp(staging_path);
    if (fd < 0) return -1;

    /* Restrict permissions to owner only */
    fchmod(fd, 0600);

    /* Unlink immediately - we only need the fd for writing,
     * then we'll use linkat or /proc/self/fd for the rename */
    unlink(staging_path);

    return fd;
}

static int write_cache_record(int fd, const dns_record_t *record) {
    if (fd < 0 || !record) return -1;

    dprintf(fd, "%s %u %u %s\n", record->qname, record->qtype,
            record->ttl, record->rdata);
    return 0;
}

/* Perform DNS resolution with caching */
int resolve_and_cache(const session_t *sess, const char *query_domain,
                      dns_record_t *result) {
    char cache_path[512];
    int staging_fd;

    if (!sess || !query_domain || !result) return -1;

    /* RBAC check */
    if (check_query_permission(sess, query_domain) != 0) {
        return -1;
    }

    /* Build cache path */
    if (get_cache_path(cache_path, sizeof(cache_path), query_domain, sess) != 0)
        return -1;

    /* Check if cached result exists */
    struct stat st;
    if (stat(cache_path, &st) == 0 && st.st_size > 0) {
        /* Cache hit - read existing */
        FILE *f = fopen(cache_path, "r");
        if (f) {
            if (fscanf(f, "%253s %hu %u %255s", result->qname, &result->qtype,
                       &result->ttl, result->rdata) == 4) {
                fclose(f);
                return 0;
            }
            fclose(f);
        }
    }

    /* Cache miss - perform resolution (simulated) */
    strncpy(result->qname, query_domain, MAX_QUERY_LEN);
    result->qname[MAX_QUERY_LEN] = '\0';
    result->qtype = 1; /* A record */
    result->ttl = 300;
    strncpy(result->rdata, "93.184.216.34", sizeof(result->rdata) - 1);

    /* Write to cache via staging file for atomicity */
    staging_fd = create_cache_staging(cache_path, sess);
    if (staging_fd >= 0) {
        write_cache_record(staging_fd, result);
        close(staging_fd);
        /* In production: rename staging -> cache_path */
    }

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <domain>\n", argv[0]);
        return 1;
    }

    session_t sess = { .role = ROLE_USER, .uid = getuid() };
    strncpy(sess.username, "resolver_user", sizeof(sess.username) - 1);

    dns_record_t result;
    memset(&result, 0, sizeof(result));

    if (resolve_and_cache(&sess, argv[1], &result) == 0) {
        printf("Resolved: %s -> %s (TTL: %u)\n",
               result.qname, result.rdata, result.ttl);
    } else {
        fprintf(stderr, "Resolution failed for: %s\n", argv[1]);
    }

    return 0;
}
